    {
      "path": "lib/wb-install-state.js",
      "content": "// 本地安装状态 + 来源锁（R8）—— ~/.dsh/armory/install-state.json 的读写层。\n//\n// 职责（对应设计 §8.3，类图 InstallStateStore）：\n//   - record(item)：按 kind+key 定位，已存在则覆盖并刷新 lastUpdated；\n//     首次写入补 installedAt。connector 不记 filesDigest，plugin/skill 记关键文件摘要。\n//   - forget(kind, key)：删除一条登记，不存在时为无害空操作。\n//   - listInstalled(kind)：返回该 kind 全部条目（顺序 = 写入序），供面板做「已安装」\n//     **全量本地筛选**（不受分页影响，与技能侧 skillOnlyInstalled 只筛当前页不同）。\n//\n// 三类安装（connector=profile、skill=目录、plugin=宿主 bundle）在各自收尾点调用 record，\n// 把分散的安装事实收敛到这一个文件里——这就是「来源锁」：登记条目带 source\n// {marketplace, url, kind}，面板据此区分「本插件装的」与「其它途径来的」。\n//\n// 纯数据层：零网络。存储根目录可注入（options.rootDir / 环境变量 DSH_ARMORY_HOME），\n// 测试绝不碰真实 ~/.dsh。写盘与 lib/wb-registry.js 同用 staging + rename 原子替换。\nimport { mkdir, readFile, rename, rm, writeFile } from \"node:fs/promises\";\nimport { homedir } from \"node:os\";\nimport { join } from \"node:path\";\n\nexport const INSTALL_STATE_VERSION = 1;\n\nconst KINDS = new Set([\"connector\", \"skill\", \"plugin\"]);\n\n/** 存储根目录：显式 rootDir > 环境变量 > 真实 ~/.dsh/armory（与 wb-registry 同一解析序）。 */\nfunction armoryRoot(options = {}) {\n  return options.rootDir || process.env.DSH_ARMORY_HOME || join(homedir(), \".dsh\", \"armory\");\n}\n\n/** 状态文件绝对路径。 */\nexport function statePath(options = {}) {\n  return join(armoryRoot(options), \"install-state.json\");\n}\n\nfunction asString(value, fallback = \"\") {\n  return typeof value === \"string\" ? value : fallback;\n}\n\nfunction asTimestamp(value, fallback = 0) {\n  return typeof value === \"number\" && Number.isFinite(value) && value >= 0 ? value : fallback;\n}\n\n/**\n * 把任意原始对象规范成一条完整的 InstallStateItem：\n * 缺失字段防御性补全，畸形来源对象折成空对象而不是抛错。\n */\nexport function normalizeItem(raw) {\n  const source = raw && typeof raw.source === \"object\" && raw.source !== null ? raw.source : {};\n  const filesDigest = raw && typeof raw.filesDigest === \"object\" && raw.filesDigest !== null && !Array.isArray(raw.filesDigest)\n    ? raw.filesDigest\n    : {};\n  return {\n    kind: KINDS.has(raw?.kind) ? raw.kind : \"connector\",\n    key: asString(raw?.key).trim(),\n    name: asString(raw?.name),\n    scope: asString(raw?.scope, \"managed\"),\n    installPath: asString(raw?.installPath),\n    version: asString(raw?.version),\n    dependencies: Array.isArray(raw?.dependencies) ? raw.dependencies.map((dep) => String(dep)) : [],\n    source: {\n      marketplace: asString(source.marketplace),\n      url: asString(source.url),\n      kind: asString(source.kind),\n    },\n    installedAt: asTimestamp(raw?.installedAt, 0),\n    lastUpdated: asTimestamp(raw?.lastUpdated, 0),\n    filesDigest,\n  };\n}\n\n/** 从磁盘读原始文档；不存在/损坏一律返回 null。 */\nasync function readRawDoc(path) {\n  try {\n    return JSON.parse(await readFile(path, \"utf8\"));\n  } catch {\n    return null;\n  }\n}\n\n/** 拆出目录部分（路径既有 / 也有 \\ 的 Windows 形态）。 */\nfunction dirnameOf(path) {\n  const cut = Math.max(path.lastIndexOf(\"/\"), path.lastIndexOf(\"\\\\\"));\n  return cut > 0 ? path.slice(0, cut) : path;\n}\n\n/** 唯一临时名 + rename 原子写（与 wb-registry.writeAtomic 同一模式）：固定 `.staging`\n *  在并发登记时会互相消费对方的临时文件，rename 覆盖已存在文件所以无需先 rm。 */\nasync function writeAtomic(path, doc) {\n  await mkdir(dirnameOf(path), { recursive: true });\n  const tmp = `${path}.${process.pid}.${Date.now()}.tmp`;\n  try {\n    await writeFile(tmp, JSON.stringify(doc, null, 2));\n    await rename(tmp, path);\n  } catch (error) {\n    await rm(tmp, { force: true }).catch(() => {});\n    throw error;\n  }\n}\n\n/** 读全部条目（合并投影：文件缺失/损坏 = 空状态）。永不抛错。 */\nexport async function readState(options = {}) {\n  const raw = await readRawDoc(statePath(options));\n  const items = Array.isArray(raw?.items)\n    ? raw.items.filter((item) => item && typeof item === \"object\" && !Array.isArray(item)).map(normalizeItem)\n    : [];\n  const version = raw && typeof raw.version === \"number\" ? raw.version : INSTALL_STATE_VERSION;\n  return { version, items };\n}\n\n/**\n * 登记一条安装：同 kind+key 覆盖（刷新 lastUpdated，保留首次的 installedAt），\n * 首次写入补 installedAt。connector 不落 filesDigest（连接器装进 profile，\n * 没有关键文件可记）；plugin/skill 原样保留传入的 filesDigest。\n */\nexport async function record(item, options = {}) {\n  const normalized = normalizeItem(item);\n  if (!normalized.key) throw new Error(\"安装状态条目缺少 key，无法登记\");\n  const path = statePath(options);\n  const { items } = await readState(options);\n  const now = Date.now();\n  const index = items.findIndex((entry) => entry.kind === normalized.kind && entry.key === normalized.key);\n  if (index >= 0) {\n    const existing = items[index];\n    items[index] = {\n      ...normalized,\n      installedAt: existing.installedAt || now,\n      lastUpdated: now,\n      filesDigest: normalized.kind === \"connector\" ? {} : (Object.keys(normalized.filesDigest).length ? normalized.filesDigest : existing.filesDigest),\n    };\n  } else {\n    items.push({\n      ...normalized,\n      installedAt: now,\n      lastUpdated: now,\n      filesDigest: normalized.kind === \"connector\" ? {} : normalized.filesDigest,\n    });\n  }\n  await writeAtomic(path, { version: INSTALL_STATE_VERSION, items });\n}\n\n/** 删除一条登记（kind+key 定位）。不存在时为无害空操作。 */\nexport async function forget(kind, key, options = {}) {\n  const wantedKind = String(kind ?? \"\").trim();\n  const wantedKey = String(key ?? \"\").trim();\n  if (!wantedKind || !wantedKey) throw new Error(\"forget 需要 kind 与 key\");\n  const path = statePath(options);\n  const { items } = await readState(options);\n  const kept = items.filter((entry) => !(entry.kind === wantedKind && entry.key === wantedKey));\n  if (kept.length === items.length) return; // 没删到东西：不写盘\n  await writeAtomic(path, { version: INSTALL_STATE_VERSION, items: kept });\n}\n\n/** 该 kind 的全部已安装条目（供「已安装」全量筛选）。 */\nexport async function listInstalled(kind, options = {}) {\n  const wanted = String(kind ?? \"\").trim();\n  const { items } = await readState(options);\n  return items.filter((entry) => entry.kind === wanted);\n}\n"
    },
    {
      "path": "lib/skill-dir-times.js",
      "content": "// Skill 看板的「安装时间 + 市场原名」投影（按 skill 名字索引）。\n//\n// 为什么不按 listSkills 行里的 path 查：宿主注册表的行**不一定**带 path（字段是条件\n// 展开，lib/index.js 只透传注册表给的），实测有的版本整列都缺——按 path 查会整表静默\n// 落空。这里改为宿主自建映射：扫描标准技能根目录，读每个目录 SKILL.md 头部的\n// `name:` 字段得到「看板显示名」，建立 名字 → 目录 → 时间/原名 的映射，按名字返回。\n// 面板的每一行必有 name（看板主键），join 永不落空。\n//\n// installedAt 取值优先级（与 wb-market.wbSkillInstalled 同一口径）：\n//   ① 安装状态账本（kind=skill，按 installPath 归一对齐）登记的首次安装时间；\n//   ② 目录创建时间——重装 = rm 后 rename 换入新目录，创建时间即最近一次落盘；\n//   ③ 目录修改时间兜底（个别文件系统不吐 birthtime）。\n// 没有 SKILL.md 的目录不会被注册表发现，直接跳过；同名目录按扫描序首个优先\n// （agents 根在 dsh 根之前，与注册表的来源优先级同向）。\n// 账本命中的条目附带 marketName / marketplace / marketVersion：账本登记的是市场里的\n// 名字，看板显示的是 SKILL.md 的 name 字段——两者可以不同，投影出去供面板对应。\n//\n// 纯只读（readdir / stat / 只读 SKILL.md 头部 4KB）；账本读失败只降级到 ②③。\n// 存储根目录可注入（options.rootDir / DSH_ARMORY_HOME），home 可注入（options.home，测试用）。\nimport { open, readdir, stat } from \"node:fs/promises\";\nimport { homedir } from \"node:os\";\nimport { join } from \"node:path\";\nimport { listInstalled } from \"./wb-install-state.js\";\n\n/** join 键归一：分隔符统一 /、去尾斜杠。账本 installPath 与实际扫描目录是两套来源，\n *  Windows 下分隔符与结尾斜杠可能有差异，对齐前先拉齐形态。 */\nconst normPath = (value) => String(value || \"\").trim().replace(/[\\\\/]+/g, \"/\").replace(/\\/+$/, \"\");\n\n/** 只读文件头部 4KB——frontmatter 永远在最前面，整读大 SKILL.md 不值得。 */\nasync function head(path, bytes = 4096) {\n  const handle = await open(path, \"r\");\n  try {\n    const buffer = Buffer.alloc(bytes);\n    const { bytesRead } = await handle.read(buffer, 0, bytes, 0);\n    return buffer.toString(\"utf8\", 0, bytesRead);\n  } finally {\n    await handle.close().catch(() => {});\n  }\n}\n\n/** SKILL.md 头部 frontmatter 的 name 字段；没有 frontmatter / 没写 name 返回空串。 */\nexport function frontmatterName(text) {\n  const block = /^---\\r?\\n([\\s\\S]*?)\\r?\\n---/.exec(String(text || \"\"));\n  if (!block) return \"\";\n  const line = /^name:[ \\t]*(.+?)[ \\t]*$/m.exec(block[1]);\n  return line ? line[1].replace(/^[\"']|[\"']$/g, \"\") : \"\";\n}\n\n/**\n * 扫描技能根目录，返回「看板名字 → 安装信息」映射。\n * @param {object} payload 客户端信封：{ cwd? }（项目作用域时带项目根）\n * @returns {Promise<{info: Record<string, {installedAt: number, dir: string,\n *   marketName?: string, marketplace?: string, marketVersion?: string}>}>}\n */\nexport async function skillInstallInfo(payload = {}, options = {}) {\n  const home = options.home || homedir();\n  const roots = [\n    join(home, \".agents\", \"skills\"),\n    join(home, \".dsh\", \"skills\"),\n  ];\n  const cwd = String(payload?.cwd || \"\").trim();\n  if (cwd) {\n    roots.push(join(cwd, \".agents\", \"skills\"));\n    roots.push(join(cwd, \".dsh\", \"skills\"));\n  }\n  const ledger = await listInstalled(\"skill\", options).catch(() => []);\n  const byPath = new Map(\n    ledger.filter((row) => row && row.installPath).map((row) => [normPath(row.installPath), row]),\n  );\n  const info = {};\n  for (const root of roots) {\n    let entries = [];\n    try {\n      entries = await readdir(root);\n    } catch {\n      continue; // 根目录不存在（没装过任何市场技能 / 没有 ~/.dsh/skills）：跳过\n    }\n    for (const entry of entries) {\n      if (entry.startsWith(\".\")) continue;\n      const dir = join(root, entry);\n      let dirStat;\n      try {\n        dirStat = await stat(dir);\n      } catch {\n        continue; // 竞态删除等：跳过\n      }\n      if (!dirStat.isDirectory()) continue;\n      let name = \"\";\n      try {\n        name = frontmatterName(await head(join(dir, \"SKILL.md\")));\n      } catch {\n        continue; // 没有 SKILL.md：注册表发现不了，不进映射\n      }\n      if (!name) name = entry;\n      if (info[name]) continue; // 同名：首个根/首个目录优先\n      const hit = byPath.get(normPath(dir));\n      const bornAt = Math.round(Number(dirStat.birthtimeMs) || 0);\n      const row = {\n        installedAt: (hit?.installedAt || 0) || bornAt || Math.round(Number(dirStat.mtimeMs) || 0),\n        dir,\n      };\n      if (hit?.name) {\n        row.marketName = hit.name;\n        row.marketplace = hit.source?.marketplace || \"\";\n        row.marketVersion = hit.version || \"\";\n      }\n      info[name] = row;\n    }\n  }\n  return { info };\n}\n"
    },
    {
      "path": "lib/skill-remove.js",
      "content": "// 已安装 skill 的卸载数据层（Skill 看板「卸载」的唯一落盘点）。\n//\n// 为什么不让客户端传路径直接删：path 来自 listSkills 的回包，但 RPC 入参是浏览器可写的。\n// 这里只认「宿主注册表给这条 skill 的真实 source + path」，并且把删除范围钉死在四类\n// skills 根目录里——用户级 ~/.agents/skills、~/.dsh/skills，项目级 <cwd>/.agents/skills、\n// <cwd>/.dsh/skills。随 DSH 分发（bundled）、运行时注册（runtime）、自定义目录（custom）\n// 一律拒绝：前两者不该由用户面板删，后者没有可信的根目录可用来做包含性校验。\n//\n// 安全闸门（按顺序，任一不过即抛错，绝不\"尽力而为\"地删）：\n//   1. source 在白名单内，且能推导出绝对根目录（项目级必须有 cwd）；\n//   2. path 是绝对路径，且 resolve 后严格位于根目录内（≠ 根自身，`..` 穿越不过）；\n//      宿主注册表返回的 path 通常指向 `<skill>/SKILL.md`，先归一化到其父目录再校验，\n//      否则会把 SKILL.md 当成「不是目录」误拒（GUI 验证抓到的真实形态）；\n//   3. 父目录的 realpath 必须仍在根目录 realpath 内（防祖先符号链接把写入面带到别处）；\n//   4. 目标是符号链接 → 只 unlink 链接本身，**绝不**触碰链接指向的目录；\n//   5. 目标是目录 → 其 realpath 仍在根内，且目录里确实有 SKILL.md（文件），才递归删除。\n//\n// 删除是**永久删除**（不进回收站）：UI 侧有二次确认，并明示不可撤销。这与用户对删除的\n// 偏好一致；不做「移到 .trash」这类软删除——那会让看板显示已卸载、磁盘却仍在。\n//\n// 纯数据层：零网络、零宿主依赖；home / cwd 可注入，测试用 mkdtemp 隔离。\nimport { lstat, realpath, rm, stat, unlink } from \"node:fs/promises\";\nimport { homedir } from \"node:os\";\nimport { basename, dirname, isAbsolute, join, relative, resolve } from \"node:path\";\n\n/** 可卸载来源：值与宿主注册表的 skill.source 一致，客户端 SKILL_REMOVABLE_SOURCES 必须同步。 */\nexport const REMOVABLE_SKILL_SOURCES = [\"user-agents\", \"user-dsh\", \"project-agents\", \"project-dsh\"];\n\n/**\n * 来源 → skills 根目录。project-* 需要 cwd；拿不到时返回 null（拒绝，而不是猜一个目录）。\n * 只写「从哪来」，不校验存在性——存在性在删除流程里按目标路径判断。\n */\nexport function skillRootFor(source, options = {}) {\n\tconst home = options.home || homedir();\n\tconst cwd = options.cwd;\n\tswitch (source) {\n\t\tcase \"user-agents\": return join(home, \".agents\", \"skills\");\n\t\tcase \"user-dsh\": return join(home, \".dsh\", \"skills\");\n\t\tcase \"project-agents\": return cwd ? join(cwd, \".agents\", \"skills\") : null;\n\t\tcase \"project-dsh\": return cwd ? join(cwd, \".dsh\", \"skills\") : null;\n\t\tdefault: return null;\n\t}\n}\n\n/** 严格包含：child 在 parent 之内且不等于 parent。 */\nfunction isInside(parent, child) {\n\tconst rel = relative(parent, child);\n\treturn rel !== \"\" && !rel.startsWith(\"..\") && !isAbsolute(rel);\n}\n\n/** 包含或相等：符号链接项只做父目录校验，父目录可以就是根。 */\nfunction isInsideOrEqual(parent, child) {\n\tconst rel = relative(parent, child);\n\treturn rel === \"\" || (!rel.startsWith(\"..\") && !isAbsolute(rel));\n}\n\nfunction describeSource(source) {\n\treturn source ? `「${source}」` : \"未知来源\";\n}\n\n/**\n * 从磁盘永久删除一条已发现的 skill。\n *\n * @param {{ name?: string, source?: string, path?: string }} skill 宿主注册表返回的条目（path 可为目录或目录内的 SKILL.md）\n * @param {{ cwd?: string, home?: string }} [options]\n * @returns {Promise<{ path: string, kind: \"symlink\" | \"dir\" }>}\n */\nexport async function removeSkillFromDisk(skill, options = {}) {\n\tconst source = typeof skill?.source === \"string\" ? skill.source : \"\";\n\tconst root = skillRootFor(source, options);\n\tif (!root) {\n\t\tif (source === \"project-agents\" || source === \"project-dsh\") {\n\t\t\tthrow new Error(`卸载项目级 skill 需要当前项目路径（来源：${describeSource(source)}）`);\n\t\t}\n\t\tthrow new Error(`这个 skill 来自${describeSource(source)}，不在可卸载范围内（只支持用户级/项目级的 .dsh/skills 与 .agents/skills）`);\n\t}\n\tif (!isAbsolute(root)) throw new Error(\"拒绝卸载：无法确定 skills 根目录的绝对路径\");\n\tconst raw = typeof skill?.path === \"string\" ? skill.path.trim() : \"\";\n\tif (!raw) throw new Error(\"这个 skill 没有可卸载的磁盘路径（运行时注册的 skill 不落盘）\");\n\tif (!isAbsolute(raw)) throw new Error(\"拒绝卸载：skill 路径不是绝对路径\");\n\n\tconst rawAbs = resolve(raw);\n\t// 注册表把 skill.path 指向清单文件（<skill>/SKILL.md），删除目标是它所在的目录。\n\t// 若直接拿清单路径去删，只会得到「该路径不是目录」——真实 GUI 首跑就撞上了。\n\tconst target = basename(rawAbs).toLowerCase() === \"skill.md\" ? dirname(rawAbs) : rawAbs;\n\tconst rootAbs = resolve(root);\n\tif (!isInside(rootAbs, target)) {\n\t\tthrow new Error(`拒绝卸载：skill 路径不在预期的 skills 根目录内（${rootAbs}）`);\n\t}\n\n\tlet info;\n\ttry {\n\t\tinfo = await lstat(target);\n\t} catch (error) {\n\t\tif (error?.code === \"ENOENT\") throw new Error(\"这个 skill 已经不在磁盘上了（可能刚被移动或删除）\");\n\t\tthrow error;\n\t}\n\n\t// 父目录的 realpath 校验：防「根内路径 → 祖先符号链接实际指向根外」。根目录本身是\n\t// 符号链接（例如 ~/.agents → 别处）是允许的，所以比的是 realpath 后的根。\n\tconst rootReal = await realpath(rootAbs);\n\tconst parentReal = await realpath(dirname(target));\n\tif (!isInsideOrEqual(rootReal, parentReal)) {\n\t\tthrow new Error(\"拒绝卸载：skill 路径经符号链接指向了 skills 根目录之外\");\n\t}\n\n\tif (info.isSymbolicLink()) {\n\t\t// 只删链接本身。链接可能指向任意位置（例如 tabbit 这种外部安装的 skill），\n\t\t// rm/lstat 都不会跟随，但我们仍显式只用 unlink，语义一目了然。\n\t\tawait unlink(target);\n\t\treturn { path: target, kind: \"symlink\" };\n\t}\n\tif (!info.isDirectory()) throw new Error(\"拒绝卸载：该路径不是目录（也不是符号链接）\");\n\n\tconst targetReal = await realpath(target);\n\tif (!isInside(rootReal, targetReal)) {\n\t\tthrow new Error(\"拒绝卸载：skill 目录经符号链接指向了 skills 根目录之外\");\n\t}\n\tconst manifest = await stat(join(target, \"SKILL.md\")).catch(() => null);\n\tif (!manifest || !manifest.isFile()) {\n\t\tthrow new Error(\"拒绝卸载：目录里没有 SKILL.md，看起来不是 skill 目录\");\n\t}\n\tawait rm(target, { recursive: true, force: false });\n\treturn { path: target, kind: \"dir\" };\n}\n"
    },
    {
      "path": "lib/tool-ledger.js",
      "content": "// 工具裁缝（Tool Tailor）——宿主侧工具使用账本。\n//\n// 数据源是本机会话日志 `~/.dsh/sessions/<项目键>/<session-*>/session.*.jsonl(.zstd)`：\n//   - `tool/call` 事件：`data.callId / data.name / data.turn / data.step`，`time` 为 epoch 毫秒；\n//   - `tool/result` 事件：`data.message.toolCallId` 与 call 配对，`data.message.isError` 判成败，\n//     与 call 的时间差即延迟。\n// 日志按落盘时机追加为**多个独立 zstd 帧**（`zlib.zstdDecompressSync` 只解第一帧，这是\n// dsh-forget-session 里踩过的坑），所以必须按 magic 切帧逐帧解压。\n//\n// 两路数据在这里合并成一张账：\n//   1. 会话日志扫描 → 每个工具的调用次数 / 错误数 / 最后使用时间（窗口内）；\n//   2. 当前注册表的 Schema（ctx.tools.schemas()）→ 每个工具每次请求占用的上下文 token 估算。\n// 窗口内零调用的 MCP 工具就是「裁缝建议」：它们既不干活，还每轮请求白收上下文税。\n//\n// §6.1 第三路（同一趟扫描，不额外遍历）：`request/header` 事件的 `data.header.tools` 里存着\n// **该次请求真实下发给模型的工具清单**。上下文税此前只有「注册表当前快照」这一个口径，它是\n// Schema 长度的纯函数，与时间完全无关 —— 于是用户连着几天看到同一个数字，既无法判断裁缝是否\n// 还在工作，也无法判断「我改注册表之后到底降了没有」。真实下发清单补上的是时间维度：按天采样\n// 就能回答「这份清单这几天变过没有、什么时候变的」，并且和注册表快照互为对照（不一致 = 宿主没\n// 重启 / 新工具尚未生效，这类状态此前完全不可见）。\n//\n// 全程只读：不写任何文件、不碰会话目录内容。\n\nimport zlib from \"node:zlib\";\nimport { homedir } from \"node:os\";\nimport { readdir, readFile, stat } from \"node:fs/promises\";\nimport { join } from \"node:path\";\nimport { setImmediate } from \"node:timers\";\n\nconst SESSIONS_DIR_SEGMENTS = [\".dsh\", \"sessions\"];\nconst MCP_PREFIX = \"mcp__\";\n/** §6.4 宿主里「参数带名字」的内置工具：技能调用都从这里走。 */\nconst SKILL_TOOL_NAME = \"skill\";\n/** 每处理这么多文件让出一次事件循环，避免大库扫描把宿主卡住。 */\nconst YIELD_EVERY = 16;\n\n/**\n * `zlib.zstdDecompressSync` 是 Node >= 22.15 才有的 API。缺失时**绝对不能**静默把每个帧\n * 都当成「损坏」吞掉：那会让工具裁缝表现为「扫到了 N 个会话、读到了 N 个日志、调用数整列 0」，\n * 而界面上看不到任何原因 —— 与「只看零调用」筛选的界面表现完全一致，无法自证清白。\n * 所以这里探测一次，让失败有名字（OPT-01）。\n */\nconst ZSTD_SUPPORTED = typeof zlib.zstdDecompressSync === \"function\";\nconst ZSTD_UNAVAILABLE_MESSAGE =\n\t\"zstd 解压不可用：当前 Node 不支持 zlib.zstdDecompressSync（需 Node >= 22.15）\";\n\n/**\n * 单个日志的**落盘体积**上限（OPT-06）。完整链路是「整块读入 → 逐帧解压 → Buffer.concat\n * → toString(utf8) → split(换行)」，峰值内存约为压缩体积的 5~10 倍；没有上限意味着一个异常\n * 长的会话日志就能拖垮主进程。64 MB 相对当前最大单文件（4.4 MB）有十四倍冗余，正常使用碰不到。\n */\nconst MAX_LOG_BYTES = 64 * 1024 * 1024;\n/** 解压文本缓存预算：按**字节**控制而非只按条数（见 textCache 注释）。 */\nconst TEXT_CACHE_MAX_BYTES = 128 * 1024 * 1024;\nconst TEXT_CACHE_MAX_ENTRIES = 32;\n\n/**\n * 真实下发工具清单的**种类上限**（§6.1）。每种只在首次出现时算一次全量税，超出后不再新增、\n * 只把 `wireTaxTruncated` 置真并交给界面上屏。设这道闸是因为「每次请求清单都不一样」这种病态\n * 日志会让 wireTaxByKey 无界增长，而那恰恰是要靠趋势线暴露的场景——宁可少报几种并明确说「已\n * 截断」，也不能让只读账本把宿主主进程的内存吃掉。\n */\nconst WIRE_TAX_MAX_KEYS = 64;\n\n/**\n * §6.4 `callId → 技能名` 的映射上限。它只在「等结果回来把错误算到技能头上」这一件事上用，\n * 而工具账本本来就为每个工具记着 `seenCallIds`，这里只是同一件事的技能版本。上限的作用与\n * WIRE_TAX_MAX_KEYS 同理：日志长度不可控时不能让它无界增长；超出后停止登记新映射，\n * 已登记的照常配对，未配对的错误数最多偏少（不会偏多）。\n */\nconst SKILL_CALL_MAP_MAX = 20_000;\n\n\n/** 把字节数格式化成 MB 文案，只用于诊断信息。 */\nfunction formatMB(bytes) {\n\treturn `${(bytes / 1_048_576).toFixed(1)} MB`;\n}\n\n/**\n * 解压**多帧** zstd 缓冲（宽容版）。与 dsh-forget-session 的 zstdDecompressAllFrames 同思路：\n * 按 zstd magic（0x28B52FFD）切帧逐帧解压；单帧文件行为不变。\n * 差别在于：个别帧损坏时跳过该帧继续（账本宁可少算一段也不整个失败），并回报帧数。\n * @param {Buffer} buf - 原始 zstd 字节。\n * @returns {{ text: string, frames: number, failedFrames: number }}\n */\nfunction zstdDecompressAllFramesLenient(buf) {\n\t// 硬守卫（OPT-01）：Node 太旧时**必须**抛出一个有名字的错误，让 scanSessionLedger 的\n\t// failures() 捕获并写进 failedFileSamples 上屏，而不是逐帧 try/catch 各自吞掉、静默全 0。\n\tif (!ZSTD_SUPPORTED) throw new Error(ZSTD_UNAVAILABLE_MESSAGE);\n\tconst MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);\n\tconst starts = [];\n\tlet idx = buf.indexOf(MAGIC, 0);\n\twhile (idx !== -1) {\n\t\tstarts.push(idx);\n\t\tidx = buf.indexOf(MAGIC, idx + 4);\n\t}\n\tif (starts.length === 0) throw new Error(\"not a zstd buffer\");\n\tconst parts = [];\n\tlet failedFrames = 0;\n\tfor (let i = 0; i < starts.length; i++) {\n\t\tconst end = i + 1 < starts.length ? starts[i + 1] : buf.length;\n\t\ttry {\n\t\t\tparts.push(zlib.zstdDecompressSync(buf.subarray(starts[i], end)));\n\t\t} catch {\n\t\t\tfailedFrames += 1;\n\t\t}\n\t}\n\treturn { text: Buffer.concat(parts).toString(\"utf8\"), frames: starts.length, failedFrames };\n}\n\n/**\n * 解压文本的跨调用缓存（OPT-03）。收益主体在这里：扫描耗时绝大部分花在「读盘 + 逐帧解压\n * + utf8 解码」上，JSON 解析只占小头。\n *\n * 两条纪律：\n *   1. 键是**日志绝对路径**，戳是 `size:mtimeMs`。日志是追加写，写必然同时抬升 size 与 mtime，\n *      所以戳一变就失效，不会拿到陈旧数据；反过来，戳没变时内容按定义没有变化。\n *   2. 淘汰按**字节预算**而不是只按条数。按报告里 32 条 × 解压后 15 MB 估算是 480 MB 峰值，\n *      在宿主主进程里不可接受；这里 128 MB 封顶，超过就按 LRU 丢到预算以内。\n * 只缓存 scanSessionLedger 需要的那点数据（解压文本 + 帧统计），不缓存任何调用记录。\n */\nconst textCache = new Map(); // logPath -> { stamp, bytes, text, frames, failedFrames }\nlet textCacheBytes = 0;\n\nfunction dropCacheEntry(logPath) {\n\tconst entry = textCache.get(logPath);\n\tif (entry) {\n\t\ttextCacheBytes -= entry.bytes;\n\t\ttextCache.delete(logPath);\n\t}\n}\n\nfunction rememberCacheEntry(logPath, entry) {\n\tdropCacheEntry(logPath);\n\ttextCache.set(logPath, entry);\n\ttextCacheBytes += entry.bytes;\n\t// Map 的迭代顺序即插入顺序，队首就是最久未使用的一条。\n\twhile (textCache.size > TEXT_CACHE_MAX_ENTRIES || textCacheBytes > TEXT_CACHE_MAX_BYTES) {\n\t\tconst oldest = textCache.keys().next();\n\t\tif (oldest.done) break;\n\t\tdropCacheEntry(oldest.value);\n\t}\n}\n\n/**\n * 读取并解压一个日志文件，命中缓存则完全跳过 IO 与解压。\n * @param {string} logPath - 日志绝对路径。\n * @param {{ size: number, mtimeMs: number }} st - 已取到的 stat 结果（不额外产生 IO）。\n * @returns {Promise<{ text: string, frames: number, failedFrames: number }>}\n */\nasync function readLogTextCached(logPath, st) {\n\tconst stamp = `${st.size}:${st.mtimeMs}`;\n\tconst hit = textCache.get(logPath);\n\tif (hit && hit.stamp === stamp) {\n\t\t// 触碰一次，让它在 LRU 里回到队尾。\n\t\ttextCache.delete(logPath);\n\t\ttextCache.set(logPath, hit);\n\t\treturn hit;\n\t}\n\tconst raw = await readFile(logPath);\n\tconst value = logPath.endsWith(\".zstd\")\n\t\t? zstdDecompressAllFramesLenient(raw)\n\t\t: { text: raw.toString(\"utf8\"), frames: 0, failedFrames: 0 };\n\tconst entry = { stamp, bytes: Buffer.byteLength(value.text, \"utf8\"), ...value };\n\t// 单条就超出总预算的怪物不缓存（否则会把整个缓存挤空，还占着内存）。\n\tif (entry.bytes <= TEXT_CACHE_MAX_BYTES) rememberCacheEntry(logPath, entry);\n\treturn value;\n}\n\n/**\n * DSH 数据根（`~/.dsh` 的上一级）。优先 `DSH_SKILL_MCP_BOARD_HOME`（测试隔离用，与\n * dsh-forget-session 的 `DSH_FORGET_SESSION_HOME` 同一惯用法），否则 OS 家目录。\n * @returns {string} 家目录绝对路径。\n */\nfunction resolveHome() {\n\tconst override = process.env.DSH_SKILL_MCP_BOARD_HOME;\n\tif (override !== undefined && override !== \"\") return override;\n\treturn homedir();\n}\n\n/**\n * 上下文 token 估算。Schema 以 ASCII 为主，4 字符 ≈ 1 token 是公开常用的粗估；\n * 只用于相对比较与量级感知，不承诺精确计费。\n * @param {string} text\n * @returns {number}\n */\nfunction estimateTokens(text) {\n\treturn Math.ceil(text.length / 4);\n}\n\n/**\n * 单个工具 Schema 投影成「要下发的那段 JSON」后的上下文税。\n *\n * 注册表侧与日志真实下发侧**必须共用这一个投影**：两处各写一遍 `{name, description,\n * parameters}` 时，任何一侧改了键集合或兜底写法，「注册表快照 vs 真实下发」的偏差里就会\n * 混进口径差而不是真差异，那个偏差卡就成了长期误报的假告警。\n * @param {{name: string, description?: string, parameters?: unknown}} tool\n * @returns {number} 估算 token 数。\n */\nfunction schemaTokensOf(tool) {\n\treturn estimateTokens(JSON.stringify({ name: tool.name, description: tool.description || \"\", parameters: tool.parameters ?? null }));\n}\n\n/**\n * 一次请求真实下发的整份工具清单的税（§6.1，口径与 {@link schemaTokensOf} 逐工具一致）。\n * @param {Array<{name?: unknown, description?: unknown, parameters?: unknown}>} tools\n * @returns {{ tokens: number, toolCount: number }}\n */\nfunction wireToolsSummary(tools) {\n\tlet tokens = 0;\n\tlet counted = 0;\n\tfor (const tool of tools) {\n\t\tif (!tool || typeof tool.name !== \"string\") continue;\n\t\ttokens += schemaTokensOf(tool);\n\t\tcounted += 1;\n\t}\n\treturn { tokens, toolCount: counted };\n}\n\n/**\n * 工具清单的**廉价**内容指纹（§6.1）：只读长度与工具名，不做 stringify，所以每个请求事件都算\n * 得起；真正的税计算只在指纹第一次出现时做一次（见 WIRE_TAX_MAX_KEYS）。\n *\n * 精度取舍要说清楚：工具数相同、工具名集合相同、描述总长相同，但**参数结构**不同的两份清单\n * 会撞成同一个指纹，此时后一份沿用前一份的税值。真实改动几乎不可能同时满足这三个条件（改参数\n * 一般会带动描述或增删工具），而撞车时的失真只影响趋势线的颗粒度与 `wireTaxChanges` 的次数，\n * 主口径 `taxTotalTokens` 来自注册表快照、完全不经这里。\n * @param {Array<{name?: unknown, description?: unknown}>} tools\n * @returns {string}\n */\nfunction wireToolsFingerprint(tools) {\n\tlet count = 0;\n\tlet descLen = 0;\n\tlet hash = 5381;\n\tfor (const tool of tools) {\n\t\tif (!tool || typeof tool.name !== \"string\") continue;\n\t\tcount += 1;\n\t\tdescLen += typeof tool.description === \"string\" ? tool.description.length : 0;\n\t\tfor (let i = 0; i < tool.name.length; i++) hash = ((hash * 33) + tool.name.charCodeAt(i)) >>> 0;\n\t}\n\treturn `${count}:${descLen}:${hash >>> 0}`;\n}\n\nfunction emptyToolRecord() {\n\treturn { calls: 0, results: 0, errors: 0, seenCallIds: new Set(), firstUsedMs: null, lastUsedMs: null };\n}\n\n/** §6.4 技能维度的调用账目：`skill` 工具每调一次，参数里就写着一个技能名。 */\nfunction emptySkillRecord() {\n\treturn { calls: 0, errors: 0, seenResultIds: new Set(), firstUsedMs: null, lastUsedMs: null };\n}\n\n/**\n * 从 `skill` 工具的调用参数里取技能名。\n * 参数是**字符串化的 JSON**（`{\"name\":\"grill\"}`），解不出来就不是一次可归属的调用：\n * 这类情况必须单独计数（`skillCallsUnparsed`）而不是静默丢弃，否则界面上会表现为\n * 「skill 有 N 次调用、但按技能的表是空的」这种自相矛盾的读数。\n * @param {unknown} rawArguments\n * @returns {string|null}\n */\nfunction skillNameOf(rawArguments) {\n\tif (typeof rawArguments !== \"string\") return null;\n\tlet parsed;\n\ttry {\n\t\tparsed = JSON.parse(rawArguments);\n\t} catch {\n\t\treturn null;\n\t}\n\tconst name = parsed?.name;\n\tif (typeof name !== \"string\") return null;\n\tconst trimmed = name.trim();\n\treturn trimmed === \"\" ? null : trimmed;\n}\n\n/**\n * 按前缀归属把工具名分类到 MCP 服务器。与 mcp-registry.js 的 toolInventory 同一判定：\n * `mcp__<server>__<tool>`；服务器名自身可能含下划线，取**最长**匹配的归属，匹配到多个\n * 服务器时标为 ambiguous（不提供操作）。\n * @param {string} toolName\n * @param {string[]} mcpServerNames\n * @returns {{ kind: \"mcp\"|\"builtin\"|\"mcp-ambiguous\", server: string|null, leaf: string|null }}\n */\nfunction classifyToolName(toolName, mcpServerNames) {\n\tif (!toolName.startsWith(MCP_PREFIX)) return { kind: \"builtin\", server: null, leaf: null };\n\tconst owners = mcpServerNames.filter((name) => toolName.startsWith(`${MCP_PREFIX}${name}__`));\n\tif (owners.length === 1) {\n\t\tconst server = owners[0];\n\t\treturn { kind: \"mcp\", server, leaf: toolName.slice(`${MCP_PREFIX}${server}__`.length) };\n\t}\n\tif (owners.length > 1) return { kind: \"mcp-ambiguous\", server: null, leaf: null };\n\treturn { kind: \"builtin\", server: null, leaf: null };\n}\n\n/**\n * 扫描会话日志，产出窗口内的工具使用账本，并与当前注册表 Schema 合并。\n * @param {object} input\n * @param {number} input.days - 统计窗口（天）。\n * @param {string[]} input.mcpServerNames - 当前注册的 MCP 服务器名（用于工具名归属）。\n * @param {Array<{name: string, description?: string, parameters?: unknown}>} input.schemas - 当前全部工具 Schema。\n * @param {Set<string>} input.disabledServers - 已禁用的 MCP 服务器名。\n * @returns {Promise<object>} 账本报告（纯数据，直接作为 Remote 返回值）。\n */\nexport async function scanSessionLedger({ days, mcpServerNames, schemas, disabledServers }) {\n\tconst windowDays = Math.min(Math.max(Math.trunc(Number(days) || 30), 1), 365);\n\tconst cutoffMs = Date.now() - windowDays * 86_400_000;\n\tconst now = Date.now();\n\n\tconst usage = new Map(); // toolName -> record\n\tlet filesRead = 0;\n\tlet filesSkippedStale = 0;\n\tlet filesSkippedOversize = 0;\n\tlet failedFiles = 0;\n\tlet failedFileSamples = [];\n\tlet sessionDirs = 0;\n\tlet sessionsWithCalls = 0;\n\tlet totalCalls = 0;\n\tlet totalResults = 0;\n\tlet totalErrors = 0;\n\tlet orphanResults = 0;\n\tlet failedFrames = 0;\n\t// §6.2 无 time 的调用事件：窗口过滤写的是「time 是数字且早于 cutoff 才丢」，所以缺 time\n\t// 的事件会**无条件计入任何窗口**。当前宿主日志 100% 带数字 time（实测 6542/6542），但格式\n\t// 一变就会静默发生，而且症状恰好是「切窗口数字不动」——与本次排查的表象一模一样。宁可多一个\n\t// 恒为 0 的计数器，也不能再让这类失配无声无息。\n\tlet undatedCalls = 0;\n\t// §6.3 本次真正读到的调用事件时间跨度（**含**早于窗口、因此在下面被 `continue` 掉的那些）。\n\t// 用它才能解释「近 90 天与近 30 天输出一字不差」：机器上只有 14 天日志时，加长窗口本来\n\t// 就无从改变结果。别用日志文件 mtime 代替：追加写的 mtime 是「最后写入」而不是「最早内容」。\n\tlet scannedEventsOldestMs = null;\n\tlet scannedEventsNewestMs = null;\n\t// §5.4 逐日趋势：扫描时顺手按天分桶，不额外遍历日志。\n\t// 桶只存「窗口内的相对天序号」（0 = 最早一天，windowDays-1 = 今天），\n\t// 由界面负责渲染；返回绝对日期反而让前端多一次时区换算的机会出错。\n\tconst dayBuckets = new Array(windowDays).fill(0);\n\t// §6.4 技能维度：`skill` 工具是宿主里唯一「参数里带名字」的内置工具，所以同一个 callId\n\t// 既属于工具 `skill`，也属于某个具体技能。两本账各记各的，互不覆盖——工具表看「skill 被\n\t// 调了 59 次」，技能表看「grill 12 次、剩下 20 个一次没有」，两者回答的是不同的问题。\n\tconst skillUsage = new Map(); // skillName -> record\n\tconst skillCallOwner = new Map(); // callId -> skillName（只为把错误算到技能头上）\n\tlet totalSkillCalls = 0;\n\tlet skillCallsUnparsed = 0;\n\t// §6.1 真实下发税的按天采样。`dayTaxKeys` 每个日桶只存**当天最后一次**请求的指纹（数字与\n\t// 短串，不持有工具数组引用 —— 365 个日桶各留一份 234 项清单会常驻几十 MB，宿主主进程里不\n\t// 可接受）；`wireTaxByKey` 存每个不同清单的税，只在指纹首次出现时算一次，上限 WIRE_TAX_MAX_KEYS\n\t// 种，超出后置 `wireTaxTruncated` 而不是无界增长。成本与「清单种类数」同阶，与请求数无关。\n\tconst dayTaxKeys = new Array(windowDays); // idx -> { time, fingerprint } | undefined\n\tconst wireTaxByKey = new Map(); // fingerprint -> { firstMs, lastMs, tokens, toolCount }\n\tlet wireTaxTruncated = false;\n\n\n\tconst dayIndex = (time) => {\n\t\tif (typeof time !== \"number\") return null;\n\t\tconst offset = now - time;\n\t\tconst idx = windowDays - 1 - Math.floor(offset / 86_400_000);\n\t\treturn idx >= 0 && idx < windowDays ? idx : null;\n\t};\n\tconst failures = (reason) => {\n\t\tfailedFiles += 1;\n\t\tif (failedFileSamples.length < 20) failedFileSamples.push(reason);\n\t};\n\n\tconst sessionsRoot = join(resolveHome(), ...SESSIONS_DIR_SEGMENTS);\n\tlet projects = [];\n\ttry {\n\t\tprojects = await readdir(sessionsRoot, { withFileTypes: true });\n\t} catch {\n\t\t// 没有任何会话日志（全新安装 / 目录被清理）：空账本照常返回。\n\t\tprojects = [];\n\t}\n\n\tlet sinceYield = 0;\n\tfor (const proj of projects) {\n\t\tif (!proj.isDirectory()) continue;\n\t\tconst projDir = join(sessionsRoot, proj.name);\n\t\tlet sessDirs = [];\n\t\ttry {\n\t\t\tsessDirs = await readdir(projDir, { withFileTypes: true });\n\t\t} catch {\n\t\t\tcontinue;\n\t\t}\n\t\tfor (const sess of sessDirs) {\n\t\t\tif (!sess.isDirectory()) continue;\n\t\t\tconst sessDir = join(projDir, sess.name);\n\t\t\tsessionDirs += 1;\n\t\t\tlet logFiles = [];\n\t\t\ttry {\n\t\t\t\tlogFiles = (await readdir(sessDir)).filter((n) => n.startsWith(\"session.\"));\n\t\t\t} catch {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tfor (const logName of logFiles) {\n\t\t\t\tconst logPath = join(sessDir, logName);\n\t\t\t\tlet st;\n\t\t\t\ttry {\n\t\t\t\t\t// mtime 早于窗口起点 → 里面不可能有窗口内事件，整个文件跳过。\n\t\t\t\t\t// 依据：日志是追加写，追加必然抬升 mtime。\n\t\t\t\t\tst = await stat(logPath);\n\t\t\t\t} catch {\n\t\t\t\t\tfailures(`${logPath}: stat failed`);\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tif (st.mtimeMs < cutoffMs) {\n\t\t\t\t\tfilesSkippedStale += 1;\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\t// 尺寸闸门放在读盘之前（OPT-06）：超限就降级跳过，并把原因交给 failures()\n\t\t\t\t// 上屏，而不是先整块读进来再发现内存不够。\n\t\t\t\tif (st.size > MAX_LOG_BYTES) {\n\t\t\t\t\tfilesSkippedOversize += 1;\n\t\t\t\t\tfailures(`${logPath}: 日志 ${formatMB(st.size)} 超过 ${formatMB(MAX_LOG_BYTES)} 上限，已跳过`);\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tlet loaded;\n\t\t\t\ttry {\n\t\t\t\t\tloaded = await readLogTextCached(logPath, st);\n\t\t\t\t} catch (error) {\n\t\t\t\t\tfailures(`${logPath}: ${error instanceof Error ? error.message : String(error)}`);\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tconst text = loaded.text;\n\t\t\t\tfailedFrames += loaded.failedFrames;\n\t\t\t\tfilesRead += 1;\n\t\t\t\tlet dirHadCall = false;\n\t\t\t\tfor (const line of text.split(\"\\n\")) {\n\t\t\t\t\tif (!line.startsWith(\"{\")) continue;\n\t\t\t\t\tlet event;\n\t\t\t\t\ttry {\n\t\t\t\t\t\tevent = JSON.parse(line);\n\t\t\t\t\t} catch {\n\t\t\t\t\t\tcontinue;\n\t\t\t\t\t}\n\t\t\t\t\tconst time = typeof event.time === \"number\" ? event.time : null;\n\t\t\t\t\t// §6.3 先记时间跨度，再做窗口过滤：被窗口丢掉的事件同样是「本机日志里真实存在过的\n\t\t\t\t\t// 调用记录」，界面要用它解释「把窗口从 30 天加到 90 天为什么什么都没变」。\n\t\t\t\t\tif (event.type === \"tool/call\" && time !== null) {\n\t\t\t\t\t\tif (scannedEventsOldestMs === null || time < scannedEventsOldestMs) scannedEventsOldestMs = time;\n\t\t\t\t\t\tif (scannedEventsNewestMs === null || time > scannedEventsNewestMs) scannedEventsNewestMs = time;\n\t\t\t\t\t}\n\t\t\t\t\tif (time !== null && time < cutoffMs) continue;\n\t\t\t\t\tif (event.type === \"tool/call\") {\n\t\t\t\t\t\tconst name = typeof event.data?.name === \"string\" ? event.data.name : null;\n\t\t\t\t\t\tconst callId = typeof event.data?.callId === \"string\" ? event.data.callId : null;\n\t\t\t\t\t\tif (!name) continue;\n\t\t\t\t\t\t// §6.2 计到账上了但没有 time → 这条落在哪个窗口都无法判定，它已经在**任何**窗口\n\t\t\t\t\t\t// 里被计数（含下面的 1 天窗口）。这是口径失配，必须单独报出去。\n\t\t\t\t\t\tif (time === null) undatedCalls += 1;\n\n\t\t\t\t\t\tlet record = usage.get(name);\n\t\t\t\t\t\tif (!record) {\n\t\t\t\t\t\t\trecord = emptyToolRecord();\n\t\t\t\t\t\t\tusage.set(name, record);\n\t\t\t\t\t\t}\n\t\t\t\t\t\trecord.calls += 1;\n\t\t\t\t\t\ttotalCalls += 1;\n\t\t\t\t\t\tdirHadCall = true;\n\t\t\t\t\t\tconst bucket = dayIndex(time);\n\t\t\t\t\t\tif (bucket !== null) dayBuckets[bucket] += 1;\n\t\t\t\t\t\tif (callId) record.seenCallIds.add(callId);\n\t\t\t\t\t\tif (time !== null) {\n\t\t\t\t\t\t\tif (record.firstUsedMs === null || time < record.firstUsedMs) record.firstUsedMs = time;\n\t\t\t\t\t\t\tif (record.lastUsedMs === null || time > record.lastUsedMs) record.lastUsedMs = time;\n\t\t\t\t\t\t}\n\t\t\t\t\t\t// §6.4 同一件事的技能版本：`skill` 的参数里带着技能名，按名字再记一笔。\n\t\t\t\t\t\t// 解不出名字的调用单独计数，界面据此说明「有一部分调用无法归属」，\n\t\t\t\t\t\t// 而不是让技能表的合计悄悄小于工具表里的 skill 调用数。\n\t\t\t\t\t\tif (name === SKILL_TOOL_NAME) {\n\t\t\t\t\t\t\tconst skillName = skillNameOf(event.data?.arguments);\n\t\t\t\t\t\t\tif (skillName === null) {\n\t\t\t\t\t\t\t\tskillCallsUnparsed += 1;\n\t\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t\tlet skillRecord = skillUsage.get(skillName);\n\t\t\t\t\t\t\t\tif (!skillRecord) {\n\t\t\t\t\t\t\t\t\tskillRecord = emptySkillRecord();\n\t\t\t\t\t\t\t\t\tskillUsage.set(skillName, skillRecord);\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\tskillRecord.calls += 1;\n\t\t\t\t\t\t\t\ttotalSkillCalls += 1;\n\t\t\t\t\t\t\t\tif (callId && skillCallOwner.size < SKILL_CALL_MAP_MAX) skillCallOwner.set(callId, skillName);\n\t\t\t\t\t\t\t\tif (time !== null) {\n\t\t\t\t\t\t\t\t\tif (skillRecord.firstUsedMs === null || time < skillRecord.firstUsedMs) skillRecord.firstUsedMs = time;\n\t\t\t\t\t\t\t\t\tif (skillRecord.lastUsedMs === null || time > skillRecord.lastUsedMs) skillRecord.lastUsedMs = time;\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t} else if (event.type === \"tool/result\") {\n\t\t\t\t\t\tconst message = event.data?.message;\n\t\t\t\t\t\tconst callId = typeof message?.toolCallId === \"string\" ? message.toolCallId : null;\n\t\t\t\t\t\tif (!callId) continue;\n\t\t\t\t\t\t// §6.4 技能错误先归账：结果事件只带 callId，工具那本账要靠遍历\n\t\t\t\t\t\t// usage 反查，技能这本账直接查映射，成本更低且不受「调用在窗口外」影响。\n\t\t\t\t\t\tconst skillOwner = skillCallOwner.get(callId);\n\t\t\t\t\t\tif (skillOwner !== undefined) {\n\t\t\t\t\t\t\tconst skillRecord = skillUsage.get(skillOwner);\n\t\t\t\t\t\t\tif (skillRecord && !skillRecord.seenResultIds.has(callId)) {\n\t\t\t\t\t\t\t\tskillRecord.seenResultIds.add(callId);\n\t\t\t\t\t\t\t\tif (message.isError === true) skillRecord.errors += 1;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t\t// 与 call 配对：同一 callId 的后续 result（重试/续写）不再重复计。\n\t\t\t\t\t\tlet owner = null;\n\t\t\t\t\t\tfor (const record of usage.values()) {\n\t\t\t\t\t\t\tif (record.seenCallIds.has(callId)) {\n\t\t\t\t\t\t\t\towner = record;\n\t\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t\tif (!owner) {\n\t\t\t\t\t\t\t// call 事件在窗口外但 result 在窗口内：计总量，不入具体工具。\n\t\t\t\t\t\t\torphanResults += 1;\n\t\t\t\t\t\t\tcontinue;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tif (owner.results > 0 && owner.results >= owner.calls) continue; // 该 call 已有结果\n\t\t\t\t\t\towner.results += 1;\n\t\t\t\t\t\ttotalResults += 1;\n\t\t\t\t\t\tif (message.isError === true) {\n\t\t\t\t\t\t\towner.errors += 1;\n\t\t\t\t\t\t\ttotalErrors += 1;\n\t\t\t\t\t\t}\n\t\t\t\t\t} else if (event.type === \"request/header\") {\n\t\t\t\t\t\t// §6.1 该次请求真实下发给模型的整份工具清单。宿主把 `data.header.tools` 原样\n\t\t\t\t\t\t// 落盘，所以「注册表快照」有了一个可对照的真值：两者不一致就是「改了没生效」。\n\t\t\t\t\t\tconst tools = event.data?.header?.tools;\n\t\t\t\t\t\tif (!Array.isArray(tools) || tools.length === 0) continue;\n\t\t\t\t\t\t// 没有 time 的清单快照无法归入日桶，直接丢；这类事件的存在由 undatedCalls\n\t\t\t\t\t\t// 那一路负责显形，两条口径不要混在一起。\n\t\t\t\t\t\tconst taxBucket = dayIndex(time);\n\t\t\t\t\t\tif (taxBucket === null) continue;\n\t\t\t\t\t\tconst fingerprint = wireToolsFingerprint(tools);\n\t\t\t\t\t\tconst known = wireTaxByKey.get(fingerprint);\n\t\t\t\t\t\tif (!known) {\n\t\t\t\t\t\t\tif (wireTaxByKey.size >= WIRE_TAX_MAX_KEYS) {\n\t\t\t\t\t\t\t\twireTaxTruncated = true;\n\t\t\t\t\t\t\t\tcontinue;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\tconst summary = wireToolsSummary(tools);\n\t\t\t\t\t\t\twireTaxByKey.set(fingerprint, { fingerprint, firstMs: time, lastMs: time, ...summary });\n\t\t\t\t\t\t} else if (time > known.lastMs) known.lastMs = time;\n\t\t\t\t\t\tconst dayBest = dayTaxKeys[taxBucket];\n\t\t\t\t\t\tif (!dayBest || time > dayBest.time) dayTaxKeys[taxBucket] = { time, fingerprint };\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif (dirHadCall) sessionsWithCalls += 1;\n\t\t\t\tsinceYield += 1;\n\t\t\t\tif (sinceYield >= YIELD_EVERY) {\n\t\t\t\t\tsinceYield = 0;\n\t\t\t\t\tawait new Promise((resolve) => setImmediate(resolve));\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// 第二遍无需：精确延迟需要 callId→callTime 全量映射，内存开销不值得。健康度以\n\t// 「错误率 + 调用次数」为准，延迟统计留给后续版本的增量账本（扫描时顺手累积）。\n\n\tconst schemaByName = new Map();\n\tfor (const schema of Array.isArray(schemas) ? schemas : []) {\n\t\tif (schema && typeof schema.name === \"string\") schemaByName.set(schema.name, schema);\n\t}\n\tconst disabled = disabledServers instanceof Set ? disabledServers : new Set();\n\n\tconst tools = [];\n\tfor (const [name, record] of usage) {\n\t\tconst classification = classifyToolName(name, mcpServerNames);\n\t\ttools.push({\n\t\t\tname,\n\t\t\tkind: classification.kind,\n\t\t\tserver: classification.server,\n\t\t\tleaf: classification.leaf,\n\t\t\tcalls: record.calls,\n\t\t\terrors: record.errors,\n\t\t\terrorRate: record.calls > 0 ? record.errors / record.calls : 0,\n\t\t\tlastUsedMs: record.lastUsedMs,\n\t\t\tschemaTokens: null,\n\t\t\tserverDisabled: classification.server !== null && disabled.has(classification.server),\n\t\t});\n\t}\n\t// 注册表里有、窗口内零调用的工具：这是「裁缝建议」的主体，不扫日志永远看不见。\n\tfor (const schema of schemaByName.values()) {\n\t\tif (usage.has(schema.name)) continue;\n\t\tconst classification = classifyToolName(schema.name, mcpServerNames);\n\t\ttools.push({\n\t\t\tname: schema.name,\n\t\t\tkind: classification.kind,\n\t\t\tserver: classification.server,\n\t\t\tleaf: classification.leaf,\n\t\t\tcalls: 0,\n\t\t\terrors: 0,\n\t\t\terrorRate: 0,\n\t\t\tlastUsedMs: null,\n\t\t\tschemaTokens: schemaTokensOf(schema),\n\t\t\tserverDisabled: classification.server !== null && disabled.has(classification.server),\n\t\t});\n\t}\n\t// 有调用记录的工具也补 Schema 税（有 Schema 的才有值）。\n\tfor (const tool of tools) {\n\t\tif (tool.schemaTokens === null && schemaByName.has(tool.name)) {\n\t\t\ttool.schemaTokens = schemaTokensOf(schemaByName.get(tool.name));\n\t\t}\n\t}\n\n\tconst mcpTools = tools.filter((tool) => tool.kind === \"mcp\");\n\tconst deadTools = tools.filter((tool) => tool.calls === 0);\n\tconst deadMcpTools = deadTools.filter((tool) => tool.kind === \"mcp\");\n\tconst taxTotalTokens = tools.reduce((sum, tool) => sum + (tool.schemaTokens ?? 0), 0);\n\tconst deadMcpTaxTokens = deadMcpTools.reduce((sum, tool) => sum + (tool.schemaTokens ?? 0), 0);\n\n\t// §6.1 收尾：把按天采到的指纹换成税值，并挑出「窗口内出现过的不同清单」按首次出现时间排序。\n\t// 界面要回答的是「这份清单这几天动过没有」，所以清单种类（通常 1~5 种）远比请求条数有意义。\n\tconst wireTaxDaily = new Array(windowDays).fill(0);\n\tfor (let i = 0; i < windowDays; i++) {\n\t\tconst dayBest = dayTaxKeys[i];\n\t\tif (!dayBest) continue;\n\t\tconst entry = wireTaxByKey.get(dayBest.fingerprint);\n\t\tif (entry) wireTaxDaily[i] = entry.tokens;\n\t}\n\tconst wireTaxSnapshots = [...wireTaxByKey.values()].sort((a, b) => a.firstMs - b.firstMs);\n\t// latest = 时间最晚那次请求所用的清单（不是「最后一个非空日桶」：日桶按天存当天最后一次，\n\t// 但同一天里先后的两份清单都记在 wireTaxSnapshots 的 firstMs/lastMs 上，这里取 lastMs 最大者）。\n\tlet wireTaxLatest = null;\n\tfor (const entry of wireTaxSnapshots) {